macro_rules! deps {
    () => {
        DateTime!();
        FixedOffset!();
        NaiveDate!();
        Utc!();
    };
}

macro_rules! test_datetime_rfc2822 {
    () => {
        deps!();
        # [test] # [cfg (feature = "alloc")] fn test_datetime_rfc2822 () { let edt = FixedOffset :: east_opt (5 * 60 * 60) . unwrap () ; assert_eq ! (Utc . with_ymd_and_hms (2015 , 2 , 18 , 23 , 16 , 9) . unwrap () . to_rfc2822 () , "Wed, 18 Feb 2015 23:16:09 +0000") ; assert_eq ! (Utc . with_ymd_and_hms (2015 , 2 , 1 , 23 , 16 , 9) . unwrap () . to_rfc2822 () , "Sun, 1 Feb 2015 23:16:09 +0000") ; assert_eq ! (edt . from_local_datetime (& NaiveDate :: from_ymd_opt (2015 , 2 , 18) . unwrap () . and_hms_milli_opt (23 , 16 , 9 , 150) . unwrap ()) . unwrap () . to_rfc2822 () , "Wed, 18 Feb 2015 23:16:09 +0500") ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:59:60 +0500") , Ok (edt . from_local_datetime (& NaiveDate :: from_ymd_opt (2015 , 2 , 18) . unwrap () . and_hms_milli_opt (23 , 59 , 59 , 1_000) . unwrap ()) . unwrap ())) ; assert ! (DateTime :: parse_from_rfc2822 ("31 DEC 262143 23:59 -2359") . is_err ()) ; assert_eq ! (DateTime :: parse_from_rfc3339 ("2015-02-18T23:59:60.234567+05:00") , Ok (edt . from_local_datetime (& NaiveDate :: from_ymd_opt (2015 , 2 , 18) . unwrap () . and_hms_micro_opt (23 , 59 , 59 , 1_234_567) . unwrap ()) . unwrap ())) ; assert_eq ! (edt . from_local_datetime (& NaiveDate :: from_ymd_opt (2015 , 2 , 18) . unwrap () . and_hms_micro_opt (23 , 59 , 59 , 1_234_567) . unwrap ()) . unwrap () . to_rfc2822 () , "Wed, 18 Feb 2015 23:59:60 +0500") ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:16:09 +0000") , Ok (FixedOffset :: east_opt (0) . unwrap () . with_ymd_and_hms (2015 , 2 , 18 , 23 , 16 , 9) . unwrap ())) ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:16:09 -0000") , Ok (FixedOffset :: east_opt (0) . unwrap () . with_ymd_and_hms (2015 , 2 , 18 , 23 , 16 , 9) . unwrap ())) ; assert_eq ! (ymdhms_micro (& edt , 2015 , 2 , 18 , 23 , 59 , 59 , 1_234_567) . to_rfc2822 () , "Wed, 18 Feb 2015 23:59:60 +0500") ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:59:58 +0500") , Ok (ymdhms (& edt , 2015 , 2 , 18 , 23 , 59 , 58))) ; assert_ne ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:59:58 +0500") , Ok (ymdhms_milli (& edt , 2015 , 2 , 18 , 23 , 59 , 58 , 500))) ; assert_eq ! (DateTime :: parse_from_rfc2822 ("\t\t\tWed,\n\t\t18 \r\n\t\tFeb \u{3000} 2015\r\n\t\t\t23:59:58    \t+0500") , Ok (ymdhms (& edt , 2015 , 2 , 18 , 23 , 59 , 58))) ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Thu,\n\t13\n      Feb\n        1969\n    23:32\n             -0330 (Newfoundland Time)") , Ok (ymdhms (& FixedOffset :: east_opt (- 3 * 60 * 60 - 30 * 60) . unwrap () , 1969 , 2 , 13 , 23 , 32 , 0 ,))) ; assert_eq ! (DateTime :: parse_from_rfc2822 ("Thu,\n\t13\n      Feb\n        1969\n    23:32\n             -0330") , Ok (ymdhms (& FixedOffset :: east_opt (- 3 * 60 * 60 - 30 * 60) . unwrap () , 1969 , 2 , 13 , 23 , 32 , 0 ,))) ; assert ! (DateTime :: parse_from_rfc2822 ("31 DEC 262143 23:59 -2359") . is_err ()) ; assert ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:16:09 +00:00") . is_err ()) ; assert ! (DateTime :: parse_from_rfc2822 ("Wednesday, 18 Feb 2015 23:16:09 +0000") . is_err ()) ; assert ! (DateTime :: parse_from_rfc2822 ("Wednesday 18 Feb 2015 23:16:09 +0000") . is_err ()) ; assert ! (DateTime :: parse_from_rfc2822 ("Wed. 18 Feb 2015 23:16:09 +0000") . is_err ()) ; assert ! (DateTime :: parse_from_rfc2822 ("Wed, 18 Feb 2015 23:16:09 +0000   ") . is_err ()) ; }
    };
}

test_datetime_rfc2822!()